@triton.autotune(configs=[Config({'XBLOCK': 512}, num_warps=8), ...], key=['xnumel'])
@triton.jit
def kernel(in_ptr, out_ptr, xnumel, XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    xmask = xindex < xnumel  # boundary mask added
    tmp0 = tl.load(in_ptr + permute_index(xindex), xmask)
    tl.store(out_ptr + xindex, tmp0, xmask)

